typedef void (*Callback)(int);
void callbackA(int x) { printf("Callback A: %d\n", x); }
void callbackB(int x) { printf("Callback B: %d\n", x); }
Callback callbacks[] = { callbackA, callbackB };
int main() {
    for (int i = 0; i < 2; ++i) {
        callbacks[i](i * 10);
    }
    return 0;
}
